function NavRow({
	to,
	params,
	search,
	active,
	icon: Icon,
	leading,
	label,
	detail,
	trailing,
	lastActivityAt,
}: {
	to?: string;
	params?: Record<string, string>;
	search?: Record<string, unknown>;
	active: boolean;
	icon?: IconComponent;
	/** Custom leading glyph (e.g. EntityIcon). Wins over `icon` when set. */
	leading?: ReactNode;
	label: string;
	/** Context shown below a Recent title, before its relative activity time. */
	detail?: string;
	/** Right-aligned adornment (e.g. a record count). */
	trailing?: ReactNode;
	lastActivityAt?: number;
}) {
	const isRecent = lastActivityAt != null;
	const metadata = isRecent
		? [detail?.trim(), formatTimeAgo(lastActivityAt)]
				.filter(Boolean)
				.join(" · ")
		: null;
	const content = isRecent ? (
		<>
			<span className="block truncate text-sm">{label}</span>
