	);
	const rowClassName = cn(
		"mx-2 rounded-md text-sm transition-colors",
		isRecent ? "block px-3 py-2" : "flex items-center gap-2 py-1.5 pl-3 pr-3",
		active
			? "bg-sidebar-accent text-sidebar-accent-foreground"
			: to
				? "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
				: "text-sidebar-foreground/80",
	);
	if (!to) {
		return (
			<div data-recent-row={isRecent ? "" : undefined} className={rowClassName}>
				{content}
			</div>
		);
	}
	return (
		<Link
			to={to as "/"}
