import { AppWindow, Chrome, Terminal } from "lucide-react";
import type { ReactNode } from "react";
import { inferredPlatform } from "@/components/devices/device-display";
import type { DeviceWorkerItem } from "@/lib/api/connections";
import { buildMcpUrl } from "@/lib/mcp-url";

/**
 * First-party ways to connect: the Mac app, the Chrome extension, the CLI, an
 * MCP client, the self-hosted bridge.
 *
 * These are static — there is no table behind them and nothing to fetch. They
 * are on the connectors surface because that is where someone goes to ask
 * "what can my agents reach?", and the honest answer includes "your laptop,
 * once you install this". Previously they lived on a standalone Devices page
 * that you could only reach from a user-menu dropdown, so the answer was
 * discoverable only if you already knew it.
 *
 * What they produce, once installed, shows up on the same list as its own row:
 * the Mac app and the extension pair a device (`device_workers`), the CLI and
 * ChatGPT register as MCP clients (`oauth_clients`). The app entry is the
 * instruction sheet; the row is the thing itself.
 */

/** One instruction: a command to run, or a place to go. */
export interface ConnectorAppStep {
	label: string;
	/** Shell command, rendered as a copyable block. */
	command?: string;
	/** External destination — a store listing, a booking link. */
	href?: string;
}

export interface ConnectorAppEntry {
	/** Route segment: `/connectors/app/{id}`. */
	id: string;
	name: string;
	icon: ReactNode;
	/** The list row's second line — what it is, in a few words. */
	tagline: string;
	/** The detail page's caption — what it does once connected. */
	description: string;
	steps: ConnectorAppStep[];
	/**
	 * Platforms a paired device reports when this app is what paired it. A
	 * workspace that already has one stops being offered the app on the list;
	 * the catalog still carries it, for a second machine.
	 */
	devicePlatforms?: readonly string[];
	/**
	 * Self-hosted path: offered in the catalog, never pushed onto the list. It
	 * has no device platform of its own to detect, so without this it would be
	 * the one row that could never be satisfied and never go away.
	 */
	catalogOnly?: boolean;
}

const MAC_CONTACT_URL = "https://lobu.ai/schedule";
const CHROME_STORE_URL =
	"https://chromewebstore.google.com/detail/jhgcecbdpnoehfnhpdfihlchjddapepi";
const DOCKER_COMMAND = `docker run -d --name lobu-bridge \\
  -v lobu-state:/var/lib/lobu \\
  -e LOBU_WORKSPACE_URL=<workspace-url> \\
  ghcr.io/lobu-ai/lobu-bridge:latest`;

function brandIcon(d: string): ReactNode {
	return (
		<svg
			aria-hidden="true"
			className="h-4 w-4 shrink-0"
			viewBox="0 0 24 24"
			fill="currentColor"
		>
			<path d={d} />
		</svg>
	);
}

