/**
 * The catalog for one workspace. Owner-scoped because the MCP endpoint and the
 * CLI's configure command both carry the workspace slug — a copied command
 * that points at the wrong workspace is worse than no command.
 */
export function buildConnectorApps(ownerSlug: string): ConnectorAppEntry[] {
	const mcpUrl = buildMcpUrl(ownerSlug);
	return [
		{
			id: "owletto-mac",
			name: "Owletto for Mac",
			icon: APPLE_ICON,
			tagline: "Menu bar app for macOS",
			description:
				"Runs agents on your Mac and brings local context — Screen Time, folders, browser history, calendar — into this workspace. Currently in private beta.",
			devicePlatforms: ["macos"],
			steps: [{ label: "Book access", href: MAC_CONTACT_URL }],
		},
		{
			id: "owletto-chrome",
			name: "Owletto for Chrome",
			icon: <Chrome className="h-4 w-4 shrink-0" />,
			tagline: "Browser extension",
			description:
				"Lets agents read the page you are on and act in your logged-in browser session, and pairs this workspace for one-click connector auth.",
			devicePlatforms: ["chrome-extension"],
			steps: [{ label: "Add to Chrome", href: CHROME_STORE_URL }],
		},
		{
			id: "lobu-cli",
			name: "Lobu CLI",
			icon: <Terminal className="h-4 w-4 shrink-0" />,
			tagline: "Terminal, and local MCP tools",
			description:
				"Authenticates local tools — Claude Code, Cursor, any MCP client on your machine — against this workspace. Headless, no GUI.",
			steps: [
				{
					label: "Install and log in",
					command: `npm i -g @lobu/cli\nlobu login\nlobu memory configure --url ${mcpUrl}`,
				},
			],
		},
		{
			id: "mcp-client",
			name: "MCP client",
			icon: <AppWindow className="h-4 w-4 shrink-0" />,
			tagline: "ChatGPT, Claude, Cursor",
			description:
				"Point any MCP client at this workspace. It authenticates as the person who authorizes it and acts with that person's access — which is why each one is listed under connectors by name.",
			steps: [{ label: "Workspace MCP endpoint", command: mcpUrl }],
		},
		{
			id: "lobu-bridge",
			name: "Lobu bridge",
			icon: DOCKER_ICON,
			tagline: "Self-hosted, in a container",
			description:
				"A bridge you run yourself, on a server or VPS. Use it to host connectors that need a persistent always-on environment rather than a laptop that sleeps.",
			catalogOnly: true,
			steps: [{ label: "Run", command: DOCKER_COMMAND }],
		},
	];
}

export function findConnectorApp(
	ownerSlug: string,
	appId: string,
): ConnectorAppEntry | undefined {
	return buildConnectorApps(ownerSlug).find((app) => app.id === appId);
}

/**
 * The apps worth offering on the connectors list: everything not already
 * answered by a paired device, minus the self-hosted path.
 */
export function offerableConnectorApps(
	ownerSlug: string,
	devices: readonly DeviceWorkerItem[],
): ConnectorAppEntry[] {
	const platforms = new Set(
		devices.map((device) => inferredPlatform(device)).filter(Boolean),
	);
	return buildConnectorApps(ownerSlug).filter((app) => {
		if (app.catalogOnly) return false;
		return !app.devicePlatforms?.some((platform) => platforms.has(platform));
	});
}

