function agentsQueryOptions(slug: string) {
	return {
		queryKey: ["agents", slug] as const,
		queryFn: async (): Promise<AgentItem[]> => {
			const res = await fetchWithTimeout(agentsUrl(slug), {
				credentials: "include",
			});
			if (!res.ok) return [];
			const data = (await res.json()) as { agents?: AgentItem[] };
			return data.agents ?? [];
		},
		staleTime: 30_000,
	};
}

export function useAgents(options?: { enabled?: boolean }) {
	const { slug } = getPathScope();
	const opts = agentsQueryOptions(slug ?? "");
	return useQuery({
		...opts,
		enabled: !!slug && (options?.enabled ?? true),
	});
}

useAgents.queryOptions = (slug: string) => agentsQueryOptions(slug);

/**
 * Resolves the caller's org's system ("builder") agent id. Slug-scoped, same as
 * the other agent hooks (`GET /api/{slug}/agents/system-agent`) — the route
 * reads the org from the slug-resolved context. `slug` scopes the query key +
 * gates `enabled`.
 *
 * Only a successful response with `systemAgentId: null` means no builder is
 * provisioned; request failures must remain distinguishable from that state.
 */
export function systemAgentQueryOptions(slug: string) {
	return {
		queryKey: ["system-agent-id", slug] as const,
		queryFn: async (): Promise<{ systemAgentId: string | null }> => {
			const res = await fetchWithTimeout(agentsUrl(slug, "/system-agent"), {
				credentials: "include",
			});
			await throwIfNotOk(res, "Failed to load workspace builder");
			const data = (await res.json()) as { systemAgentId?: string | null };
			return { systemAgentId: data.systemAgentId ?? null };
		},
		staleTime: 60_000,
	};
}

export function useSystemAgentId(options?: { enabled?: boolean }) {
	const { slug } = getPathScope();
import { useMemo } from "react";
import { useAgents, useSystemAgentId } from "@/lib/api";

export function useWorkingAgents(enabled = true) {
	const { data: agents = [], ...rest } = useAgents({ enabled });
	const { data: systemAgent } = useSystemAgentId({ enabled });
	const systemAgentId = systemAgent?.systemAgentId ?? null;

	/** Non-system teammates — pickers and “working agents” that exclude Builder. */
	const workingAgents = useMemo(
		() =>
			systemAgentId
				? agents.filter((a) => a.agentId !== systemAgentId)
				: agents,
		[agents, systemAgentId],
	);

	const builderAgent = useMemo(
		() =>
			systemAgentId
				? (agents.find((a) => a.agentId === systemAgentId) ?? null)
				: null,
		[agents, systemAgentId],
	);

	/** Sidebar roster: Builder pinned first, then teammates (no duplicates). */
	const rosterAgents = useMemo(
		() => (builderAgent ? [builderAgent, ...workingAgents] : workingAgents),
		[builderAgent, workingAgents],
	);

	return {
		agents,
		workingAgents,
		rosterAgents,
		builderAgent,
		systemAgentId,
		...rest,
	};
}

