/** Resolve a brand glyph from the free-form title reported by an MCP client. */
function getAppIcon(name?: string | null): ReactNode | undefined {
	const lower = name?.trim().toLowerCase();
	if (!lower) return undefined;
	if (lower.includes("claude") || lower.includes("anthropic")) return ANTHROPIC;
	if (
		lower.includes("codex") ||
		lower.includes("chatgpt") ||
		lower.includes("openai")
	) {
		return OPENAI;
	}
	if (lower.includes("gemini")) return GEMINI;
	if (lower.includes("cursor")) return CURSOR;
	if (lower.includes("lobu")) return <LobuMark className="h-4 w-4 shrink-0" />;
	return undefined;
}

/** One recognizable MCP-client mark, with a generic fallback for custom apps. */
export function ClientAppIcon({ name }: { name?: string | null }) {
	return getAppIcon(name) ?? <AppWindow className="h-4 w-4 shrink-0" />;
}
