const USER = 'u-owner';

/** Prod row: registered "Owletto for Mac", driven by the Claude Code SDK. */
const MAC_CLIENT = 'mcp_client_owletto_mac';
/** Prod row: registered "ChatGPT", reports itself as "openai-mcp". */
const CHATGPT_CLIENT = 'mcp_client_chatgpt';

beforeAll(async () => {
